// RegisterIntents adds generated intent tools to the MCP server.
// This is called from RegisterTools when spec intents or recipe-lifted intents exist.
func RegisterIntents(s *server.MCPServer) {
	s.AddTool(
		mcplib.NewTool("trace_a_slow_agent_run",
			mcplib.WithDescription("Rebuilds the run as a timeline of paired tool calls and results with elapsed time per step and a tool-duration histogram, so the nine-second step is obvious instead of buried in a flat event array."),
			mcplib.WithString("slug", mcplib.Required(), mcplib.Description("Override the recipe's positional slug value.")),
			mcplib.WithBoolean("tools", mcplib.Description("Override the recipe's --tools value.")),
		),
		handleTraceASlowAgentRun,
	)
}

// handleTraceASlowAgentRun runs the trace_a_slow_agent_run recipe intent: Rebuilds the run as a timeline of paired tool calls and results with elapsed time per step and a tool-duration histogram, so the nine-second step is obvious instead of buried in a flat event array.
func handleTraceASlowAgentRun(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	if recipeCLIPathErr != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("companion CLI binary not found: %v", recipeCLIPathErr)), nil
	}

	input := req.GetArguments()
	args := []string{}
	args = append(args, "agent-trace")
	var missingSlug bool
	args, missingSlug = appendRecipePositional(args, input["slug"], true)
	if missingSlug {
		return mcplib.NewToolResultError("slug is required"), nil
	}
	args = appendRecipeBoolFlag(args, "tools", input["tools"], true)

	out, err := cobratree.RunCLICommand(ctx, recipeCLIPath, args)
	if err != nil {
		return mcplib.NewToolResultError(err.Error()), nil
	}
	return mcplib.NewToolResultText(bound.Text(out)), nil
}

